import{_ as n,a0 as i,w as u,s as l,ao as r,I as p,x as a,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 服务器中配置 AWStats | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 服务器中配置 AWStats | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 服务器中配置 AWStats | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 服务器中配置 AWStats | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151109 How to Set Up AWStats On Ubuntu Server","title":"如何在 Ubuntu 服务器中配置 AWStats","tag":"201512","desc":""},"relativePath":"201512/20151109 How to Set Up AWStats On Ubuntu Server.md","filePath":"[post].md"}'),d={name:"201512/20151109 How to Set Up AWStats On Ubuntu Server.md"};function w(h,t,c,m,b,S){const e=i("Link");return u(),l("div",null,[t[16]||(t[16]=r(`<h1 id="如何在-ubuntu-服务器中配置-awstats" tabindex="-1">如何在 Ubuntu 服务器中配置 AWStats <a class="header-anchor" href="#如何在-ubuntu-服务器中配置-awstats" aria-label="Permalink to “如何在 Ubuntu 服务器中配置 AWStats”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/Apache_awstats_featured.jpg" alt=""></p><p>AWStats 是一个开源的网站分析报告工具，可以生成强大的网站、流媒体、FTP 或邮件服务器的访问统计图。此日志分析器以 CGI 或命令行方式进行工作，并在网页中以图表的形式尽可能的显示你日志中所有的信息。它可以“部分”读取信息文件，以便能够频繁并快速处理大量的日志文件。它支持绝大多数 Web 服务器日志文件格式，包括 Apache，IIS 等。</p><p>本文将帮助你在 Ubuntu 上安装配置 AWStats。</p><h3 id="安装-awstats-包" tabindex="-1">安装 AWStats 包 <a class="header-anchor" href="#安装-awstats-包" aria-label="Permalink to “安装 AWStats 包”">​</a></h3><p>默认情况下，AWStats 的包可以在 Ubuntu 仓库中找到。</p><p>可以通过运行下面的命令来安装：</p><pre><code>sudo apt-get install awstats
</code></pre><p>接下来，你需要启用 Apache 的 CGI 模块。</p><p>运行以下命令来启动 CGI：</p><pre><code>sudo a2enmod cgi
</code></pre><p>现在，重新启动 Apache 以使改变生效。</p><pre><code>sudo /etc/init.d/apache2 restart
</code></pre><h3 id="配置-awstats" tabindex="-1">配置 AWStats <a class="header-anchor" href="#配置-awstats" aria-label="Permalink to “配置 AWStats”">​</a></h3><p>你需要为你想要查看统计的每个域或网站创建一个配置文件。在这个例子中，我们将为 “test.com” 创建一个配置文件。</p><p>要完成此步，你可以通过复制 AWStats 的默认配置文件来配置你要统计的域。</p><pre><code>sudo cp /etc/awstats/awstats.conf /etc/awstats/awstats.test.com.conf
</code></pre><p>现在，你需要在配置文件中做一些修改：</p><pre><code>sudo nano /etc/awstats/awstats.test.com.conf
</code></pre><p>像下面这样修改一下:</p><pre><code># Change to Apache log file, by default it&#39;s /var/log/apache2/access.log
LogFile=&quot;/var/log/apache2/access.log&quot;
 
# Change to the website domain name
SiteDomain=&quot;test.com&quot;
HostAliases=&quot;www.test.com localhost 127.0.0.1&quot;
 
# When this parameter is set to 1, AWStats adds a button on report page to allow to &quot;update&quot; statistics from a web browser
AllowToUpdateStatsFromBrowser=1
</code></pre><p>保存并关闭文件。</p><p>修改配置文件后，你需要用服务器的当前日志建立初步统计。你可以这样做：</p><pre><code>sudo /usr/lib/cgi-bin/awstats.pl -config=test.com -update
</code></pre><p>输出会是这个样子:</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/awtstats.png" alt="awtstats"></p><h3 id="为-apache-配置-awstats" tabindex="-1">为 Apache 配置 AWStats <a class="header-anchor" href="#为-apache-配置-awstats" aria-label="Permalink to “为 Apache 配置 AWStats”">​</a></h3><p>接下来，你需要配置 Apache2 来显示统计数据。现在你需要将 “cgi-bin” 文件夹中的内容复制到 Apache 默认根目录下。默认它是在 “/usr/lib/cgi-bin”。</p><p>运行以下命令来完成此步:</p><pre><code>sudo cp -r /usr/lib/cgi-bin /var/www/html/
sudo  chown www-data:www-data /var/www/html/cgi-bin/
sudo chmod -R 755 /var/www/html/cgi-bin/
</code></pre><h3 id="测试-awstats" tabindex="-1">测试 AWStats <a class="header-anchor" href="#测试-awstats" aria-label="Permalink to “测试 AWStats”">​</a></h3>`,31)),p("p",null,[t[1]||(t[1]=a("现在，您可以通过访问 url “",-1)),s(e,{href:"http://your-server-ip/cgi-bin/awstats.pl?config=test.com.%E2%80%9D"},{default:o(()=>[...t[0]||(t[0]=[a("http://your-server-ip/cgi-bin/awstats.pl?config=test.com.”",-1)])]),_:1}),t[2]||(t[2]=a(" 来查看 AWStats 的页面。",-1))]),t[17]||(t[17]=r(`<p>它的页面像下面这样：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/awstats_page.jpg" alt="awstats_page"></p><h3 id="设置定时任务来更新日志" tabindex="-1">设置定时任务来更新日志 <a class="header-anchor" href="#设置定时任务来更新日志" aria-label="Permalink to “设置定时任务来更新日志”">​</a></h3><p>建议你创建一个定时任务，使用新创建的日志条目定期更新 AWStats 的数据库，然后统计会定期更新。这也将节省你的时间。</p><p>要做到这一点，你需要编辑 “/etc/crontab” 文件:</p><pre><code>sudo nano /etc/crontab
</code></pre><p>添加下面那一行来让 AWStats 每十分钟更新一次。</p><pre><code>*/10 * * * * root /usr/lib/cgi-bin/awstats.pl -config=test.com -update
</code></pre><p>保存并关闭文件。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>AWStats 是一个非常有用的工具，可以让你对网站的状况了如指掌，并能协助你分析网站。它非常容易安装和配置。如果你有任何疑问，请在下面发表评论。</p><hr>`,12)),p("p",null,[t[4]||(t[4]=a("via: ",-1)),s(e,{href:"https://www.maketecheasier.com/set-up-awstats-ubuntu/"},{default:o(()=>[...t[3]||(t[3]=[a("https://www.maketecheasier.com/set-up-awstats-ubuntu/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=a("作者：",-1)),s(e,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:o(()=>[...t[5]||(t[5]=[a("Hitesh Jethva",-1)])]),_:1}),t[9]||(t[9]=a(" 译者：",-1)),s(e,{href:"https://github.com/strugglingyouth"},{default:o(()=>[...t[6]||(t[6]=[a("strugglingyouth",-1)])]),_:1}),t[10]||(t[10]=a(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[a("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=a("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[a("Linux中国",-1)])]),_:1}),t[15]||(t[15]=a(" 荣誉推出",-1))])])}const T=n(d,[["render",w]]);export{f as __pageData,T as default};
